function I(name,large=false){return `<svg aria-hidden="true" class="icon${large?' lg':''}" viewBox="0 0 24 24">${ICONS[name]||ICONS.shield}</svg>`}
function esc(x){return String(x??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;')}
function date(){return new Date().toISOString().slice(0,10)}
function time(){return new Date().toLocaleString('es-ES',{dateStyle:'short',timeStyle:'short'})}
