function ruleFor(cat){const g=GROUPS.find(x=>x.id===cat);return g?{period:g.period,hours:g.hours,pay:g.pay}:{period:'Pendiente',hours:null,pay:null}}
function layoutHome(){return `<div class="shell-home"><div class="home-glow"></div><header class="home-bar"><a class="home-brand" href="#/inicio" aria-label="DEA HABBO ES, volver al inicio"><img src="./logo-dea-es.png" alt="Logo oficial DEA ES"><span>DEA HABBO ES</span></a><span class="micro">HABBO HOTEL · AGENCIA</span></header><main class="landing"><div class="hero-eagle"><img src="./aguila-dea-original.jpg" alt="Águila dorada y azul del Departamento Especial de Agentes"></div><div class="hero-kicker">DEPARTAMENTO ESPECIAL DE AGENTES</div><h1 class="gradient-ink">DEA HABBO ES</h1><p class="hero-caption">Disciplina · Honor · Lealtad<br>Tu espacio de información, acceso y gestión de la agencia en Habbo Hotel.</p><span class="pill">${I('spark')} PLATAFORMA OFICIAL DE LA AGENCIA</span><div class="choice-grid dea-home-choices"><a href="#/publico" class="choice public"><span class="dea-choice-tag">ACCESO LIBRE</span>${I('globe',true)}<strong>WEB PÚBLICA</strong><small>Conoce nuestra agencia, rangos, departamentos, Founders y normativa.</small><span class="dea-choice-cta">ENTRAR AHORA ↗</span></a><a href="#/publico/ingreso" class="choice join"><span class="dea-choice-tag">REQUISITO PREVIO</span>${I('user',true)}<strong>ÚNETE A DEA</strong><small>¿Quieres formar parte de nuestra agencia?</small><span class="dea-choice-alert">⚠ PRIMERO ACUDE A LA SALA<br><em>La formación inicial de 45 minutos se realiza en Habbo. El registro web comienza en R2.</em></span><span class="dea-choice-cta">CÓMO INGRESAR EN DEA ↗</span></a><a href="#/vip" class="choice vip"><span class="dea-choice-tag">ACCESO RESTRINGIDO</span>${I('crown',true)}<strong>FOUNDER VIP</strong><small>Zona privada reservada a Founders autorizados. Requiere identificación con Discord.</small><span class="dea-choice-cta">ACCESO PRIVADO ↗</span></a></div><p class="home-desc">En Habbo Hotel, los primeros 45 minutos de formación se gestionan en la sala. El registro web comienza en R2 · Agente de Enlace.</p></main><footer class="home-foot">${deaPlate()}${DEA_LEGAL_FOOTER}</footer></div>`}
const NAV_PUBLIC=[['publico','Inicio','home'],['publico/noticias','DEA Confidencial','book'],['publico/agencia','La agencia','shield'],['publico/sala','La sala DEA','home'],['publico/founders','Founders','crown'],['publico/ingreso','Cómo ingresar','user'],['publico/como-trabajar','Cómo trabajar en DEA','book'],['publico/jerarquia','Rangos y ascensos','list'],['publico/placas','Placas de beneficio','spark'],['publico/compra-rangos','Compra de rangos','wallet'],['publico/banderines','Banderines','shield'],['publico/departamentos','Departamentos','users'],['publico/normativa','Normativa DEA','book']];
const NAV_VIP=[['vip','Acceso seguro','lock']];
const NAV_AGENT=[['unete','Acceso de agentes','user'],['ficha','Mi expediente','user']];
function area(p){if(p==='identificacion/vip')return 'vip';if(p==='identificacion/alta'||p==='identificacion/agente')return 'unete';return p.startsWith('publico')?'publico':p.startsWith('vip')?'vip':p.startsWith('ficha')?'ficha':p==='unete'?'unete':'inicio'}
function navMenu(p){const a=area(p);return a==='publico'?NAV_PUBLIC:a==='vip'?NAV_VIP:NAV_AGENT}
function deaPlate(vip=false){return '<div class="dea-plate" '+(vip?'role="button" tabindex="0" data-dea-open="1"':'')+'><img src="./logo-dea-es.png" alt="Escudo DEA"><div><small>✦ CONTROL DE VISITAS DEA</small><strong>—</strong><span role="status" aria-live="polite">Consultando visitas reales…</span></div>'+(vip?'<b>▥</b>':'')+'</div>'}
function deaModal(){return '<div class="dea-modal" data-dea-modal hidden><section role="dialog" aria-modal="true" aria-label="Centro de Inteligencia Web"><header><img src="./logo-dea-es.png" alt=""><div><small>DEA · FOUNDERS</small><h2>CENTRO DE INTELIGENCIA WEB</h2></div><button data-dea-close type="button" aria-label="Cerrar">✕</button></header><p>Estadísticas pendientes de conectar a un sistema real de analítica. No se presentan cifras inventadas.</p><div class="dea-metrics">'+['Accesos totales','Visitantes únicos','Visitas hoy','En directo','Países de procedencia','Google · Discord · Directo','Dispositivos','Rutas más frecuentes','Récord histórico','Hora punta y día estrella'].map(t=>'<div><small>'+t+'</small><strong>Sin datos</strong></div>').join('')+'</div><footer>Estadísticas agregadas · Información exclusiva de Founders</footer></section></div>'}
function internalShell(p,body){const a=area(p);const nav=navMenu(p);const t=a==='vip'?'CENTRO DE CONTROL VIP':a==='publico'?'WEB PÚBLICA':a==='unete'?'ACCESO DE AGENTES':'INTRANET · AGENTES';const sub=a==='vip'?'Dirección y operaciones internas':a==='publico'?'Información de la agencia':a==='unete'?'Entrar con Discord · Solicitud R2 y expediente personal':'Consulta personal y solo lectura';const crumb=p.split('/');const crumbs=[['Inicio','inicio']];if(crumb[0]==='publico')crumbs.push(['Web pública','publico']);if(crumb[0]==='vip')crumbs.push(['Acceso VIP','vip']);if(crumb[0]==='ficha')crumbs.push(['Mi expediente','ficha']);if(crumb[0]==='unete')crumbs.push(['Únete a DEA','unete']);if(crumb[0]==='identificacion'){const vip=crumb[1]==='vip';crumbs.push([vip?'Acceso VIP':'Únete a DEA',vip?'vip':'unete']);crumbs.push(['Identificación con Discord',p]);}if(crumb.length>1&&crumb[0]!=='identificacion')crumbs.push([({agencia:'La agencia',jerarquia:'Jerarquía','como-trabajar':'Cómo trabajar en DEA',departamentos:'Departamentos',founders:'Founders',ingreso:'Cómo ingresar',normativa:'Normativa',placas:'Placas de beneficio','compra-rangos':'Compra de rangos',sala:'La sala DEA',banderines:'Banderines',noticias:'Noticias DEA',solicitudes:'Solicitudes',agentes:'Agentes',ascensos:'Ascensos',rangos:'Rangos y normas',nominas:'Nóminas y extras',historial:'Historial',configuracion:'Configuración',pagos:'Mis pagos'})[crumb[1]]||crumb[1],p]);const isV=a==='vip';return `<div class="app-layout app-area-${a}"><div class="mobile-overlay${mobileOpen?' active':''}" data-action="close-mobile" aria-hidden="true"></div><aside class="side${sidebarOpen?' expanded':''}${mobileOpen?' mobile-open':''}" aria-label="Menú principal"><div class="side-head"><a class="brand-home" href="#/inicio" aria-label="DEA HABBO ES, volver al inicio" title="Volver al inicio"><img src="./logo-dea-es.png" alt="Escudo oficial DEA"></a><div class="side-name">DEA HABBO ES<div class="side-brand-sub">DEPARTAMENTO ESPECIAL</div></div><button class="sidebar-toggle" title="Abrir o cerrar menú" aria-label="Abrir o cerrar menú" aria-expanded="${sidebarOpen}" data-action="toggle-sidebar">${I('menu')}</button></div><nav class="side-scroll" id="dea-side-scroll"><div class="side-group">NAVEGACIÓN</div>${nav.map(([url,name,ic])=>`<a href="#/${url}" title="${esc(name)}" class="side-item${(p===url||(p==='identificacion/vip'&&url==='vip')||((p==='identificacion/alta'||p==='identificacion/agente')&&url==='unete'))?' active':''}${isV?' gold':''}">${I(ic)}<span>${esc(name)}</span>${(['publico/noticias','publico/sala','publico/compra-rangos'].includes(url))?'<small class="dea-menu-new">NEW</small>':''}</a>`).join('')}</nav><div class="side-bottom"><a href="#/inicio" title="Volver a portada" class="side-item">${I('back')}<span>Volver a portada</span></a><a href="https://www.habbo.es/" target="_blank" rel="noopener noreferrer" title="Ir a Habbo.es, sitio oficial (nueva ventana)" class="side-item habbo-official-link"><img class="habbo-official-logo" src="https://upload.wikimedia.org/wikipedia/commons/6/6f/Habbo-logo.png" alt="Logotipo Habbo" loading="lazy"><span>Habbo.es · Oficial <small>IR ↗</small></span></a>${identity?`<button type="button" class="side-item logout-link" data-action="logout">${I('logout')}<span>Cerrar sesión</span></button>`:''} </div></aside><div class="main"><header class="topbar"><div class="switch-head"><button class="btn ghost sm mobile-menu-btn" data-action="mobile-menu" aria-label="Mostrar menú" aria-expanded="${mobileOpen}">${I('menu')}</button><div><div class="topbar-title">${t}</div><div class="topbar-sub">${sub}</div></div></div><span class="topbar-badge${connected?'':' offline'}">${connected?'SISTEMA DISPONIBLE':'V6 · PREPARADO'}</span></header><main class="main-body"><div class="bread" aria-label="Ruta de navegación">${crumbs.map(([name,url],i)=>`${i?I('chevron'):''}${i===crumbs.length-1?`<b>${esc(name)}</b>`:`<button data-route="${url}">${esc(name)}</button>`}`).join('')}</div>${a==='publico'?publicNeonTabs(p):''}${body}<div class="watermark">DEA HABBO ES</div>${PUBLIC_SITE_LIVE?'':`<button class="dea-preview-exit" data-action="exit-preview" title="Cerrar la vista previa">Cerrar vista previa</button>`}</main><footer class="foot">${deaPlate(a==='vip')}${DEA_LEGAL_FOOTER}</footer>${a==='vip'?deaModal():''}</div></div>`}
function head(k,title,desc){return `<div class="section-kicker">${k}</div><h1 class="page-title">${title}</h1><p class="page-desc">${desc}</p>`}
function tile(icon,label,val,gold=false){return `<div class="tile${gold?' gold':''}">${I(icon,true)}<div class="value">${val}</div><div class="hint">${label}</div></div>`}
function button(label,action,style='ghost'){return `<button class="btn ${style}" data-action="${action}">${label}</button>`}
function deaAvatarUrl(name){return name==='XPE_34'?'./assets/dea/founder-xpe34.png':name==='Fr4nn_23'?'./assets/dea/manager-fr4nn23.png':'https://www.habbo.es/habbo-imaging/avatarimage?user='+encodeURIComponent(name)+'&direction=2&head_direction=2&action=std&gesture=sml&size=l'}
function founders(){const names=['lesslie.ar','10PEDRO','XPE_34','KietsyAndrea'];const titles={'lesslie.ar':'Coordinadora General','10PEDRO':'Coordinador de Tecnología Web','XPE_34':'Coordinador de Eventos','KietsyAndrea':'Coordinadora de RRHH'};const descriptions={'lesslie.ar':'Coordinación general de DEA · Construcción y diseño de la sede en Habbo','10PEDRO':'Desarrollo web · Sistemas digitales · Integraciones · Automatizaciones · Infraestructura tecnológica','XPE_34':'Organización de eventos · Gestión de placas y banderines · Configuración de Wired','KietsyAndrea':'Coordinación de Recursos Humanos'};return `<section class="dea-founders-intro"><span>✦ DIRECCIÓN SUPERIOR</span><h3>Los cuatro Founders y CEO de DEA</h3><p>Los cuatro son fundadores y CEO. lesslie.ar asume la Coordinación General y la coordinación ejecutiva.</p></section><div class="dea-org-level dea-org-level-founder"><span>♛ FOUNDERS · DIRECCIÓN</span><small>Dirección superior de DEA</small></div><div class="dea-founder-grid">${names.map(name=>`<article class="dea-founder-card${name==='lesslie.ar'?' dea-founder-coordinator':''}"><span class="dea-founder-rank">♛ FOUNDER</span><div class="dea-founder-art"><img src="${deaAvatarUrl(name)}" alt="Avatar de Habbo de ${esc(name)}" loading="lazy" referrerpolicy="no-referrer" onerror="this.style.display='none'"></div><h4>${esc(name)}</h4><p>CEO${titles[name]?` · ${esc(titles[name])}`:''}</p>${descriptions[name]?`<small class="dea-founder-description">${esc(descriptions[name])}</small>`:''}</article>`).join('')}</div><div class="dea-org-connector" aria-hidden="true"></div><section class="dea-confirmed-staff"><div class="dea-org-level dea-org-level-manager"><span>◆ MÁNAGERS</span><small>Gestión y coordinación</small></div><article class="dea-confirmed-manager"><div class="dea-manager-art"><img src="${deaAvatarUrl('Fr4nn_23')}" alt="Avatar de Habbo de Fr4nn_23" loading="lazy"></div><div><strong>Fr4nn_23</strong><span>Mánager de PBL</span><small>Cargo confirmado en DEA</small></div></article></section>`}
const DEA_CHAT_COLORS=[{name:'Blanco',color:'#ffffff',bg:'#34485c'},{name:'Blanco',color:'#ffffff',bg:'#34485c'},{name:'Amarillo',color:'#facc15',bg:'#393522'},{name:'Verde',color:'#4ade80',bg:'#193d35'},{name:'Negro',color:'#111111',bg:'#dce4ea'},{name:'Azul',color:'#60a5fa',bg:'#193b61'},{name:'Rojo',color:'#fb7185',bg:'#482b3b'},{name:'Azul claro',color:'#7dd3fc',bg:'#164b62'},{name:'Rosa',color:'#f9a8d4',bg:'#542b48'},{name:'Libre',color:'#f0d08b',bg:'#3d4250'}];
function deaChatLabel(rank){const i=Number(String(rank).replace(/^R/,''))-1;const x=DEA_CHAT_COLORS[i];return x?'<span class="dea-chat-label" style="--chat-ink:'+x.color+';--chat-bg:'+x.bg+'">Chat '+esc(x.name)+'</span>':''}
function groups(showEditor=false){return GROUPS.map(g=>{let r=ruleFor(g.id);return `<details class="rank-row" id="rank-${g.id}"><summary><div><strong>${g.id} · ${g.label}</strong>${deaChatLabel(g.id)}${g.id==='R9'?'<small class="dea-sales-note">VENTAS · 15 % comisión</small>':g.id==='R10'?'<small class="dea-sales-note">VENTAS · 30 % comisión</small>':''}<div><small>${esc(r.period)} · ${r.pay===null?'Nómina por definir':r.pay+' créditos'}${r.hours===null?'':' · '+r.hours+' h de presencia'}</small></div></div>${I('chevron')}</summary><div class="rank-inner"><div class="rank-pills">${g.ranks.length?g.ranks.map(x=>`<span>${esc(x)}</span>`).join(''):'<span>Rangos internos pendientes de definir</span>'}</div>${g.note?`<p class="dim">${esc(g.note)}</p>`:''}</div></details>`}).join('')}
const DEA_OFFICIAL_ROLES=[["Formación","Blanco","15 minutos · 3 misiones","45 minutos","No indicada",["Permanecer 45 minutos en base durante pre-registro y capacitación a cargo del Cuerpo Élite.","Los 45 minutos comienzan al reclutar.","El tiempo y ascenso los gestiona Dirección de Cadetes; en su ausencia, cualquier Director."]],["Agentes","Blanco","Cada 2 horas","3 horas","7c",["Reclutar personal.","Asignar misión [DEA] Aprendiz.","Ascensos por Dirección de Agentes."]],["Cuerpo Élite","Amarillo","Cada 4 horas","6 horas","12c",["Seguridad de la base y comprobación del color de chat.","Exigir uniforme completo y lectura de reglas, pagas y placas de beneficios.","Pedir dos reglas y utilizar el comando :PASAR.","Ascensos solo por Dirección de Cuerpo Élite."]],["Logística","Verde","Cada 12 horas","7 horas","14c",["Ayudar en registro y acceso a la web.","Explicar plazos de ascenso y control de tiempo a reclutas.","Apoyar entrada o recepción cuando sea necesario."]],["Supervisor","Negro","Cada 5 días","8 horas","16c",["Apoyar a RR. HH. abriendo y cerrando tiempos de agentes sentados en recepción de time.","Pasar lista cada 15 minutos solo en recepción y detener tiempo a ausentes."]],["Director","Azul","Cada 15 días","8 horas","18c",["Organizar los ascensos de su departamento."]],["Delegados","Rojo","Cada 25 días","No indicadas","22c",["Apoyar las tareas de R3 y R4 y velar por su funcionamiento."]],["Secretarios","Azul claro","Por méritos y elección de Founders","No indicadas","33c",["Tramitar solicitudes de time para web y comprobar su inicio y finalización.","Comprobar y aceptar placas de nómina y bonificación según el procedimiento.","Gestionar quejas, encuestas y propuestas en RR. HH.","Actualizar registros de tiempos y bonificaciones."]],["Líderes (Administración)","Rosa","Elección de Founders y evaluación continua","No indicadas","35c de nómina + 15% de comisión por ventas",["Aceptar placas para subidas de rango.","Velar por el funcionamiento cuando no estén Founders o Managers.","Referencia semanal indicada: 70c; comisiones del 15% sobre ventas."]],["Managers","Libre","No indicado","No indicadas","80c semanales + 30% comisión por ventas",["Responsabilidad máxima operativa según el documento.","Moderar usuarios y gestionar avisos, expulsiones y despidos.","Actualizar diariamente los registros.","Vender placas de beneficios, VIP y misiones.","Primera de dos pagas: 40c + 30% de comisión; segunda paga sin detalle en el documento."]]];
const DEA_PAY_INFO=[null,['17 c','7 c'],['27 c','12 c'],['31 c','14 c'],['35 c','16 c (configuración previa; pendiente de cotejar)'],['39 c','18 c'],['47 c (44 c ordinarios + 3 c de bonificación)','22 c'],['69 c','33 c'],['70 c (referencia)','35 c + 15 % de ventas'],[null,'80 c semanales + 30 % de ventas']];
function deaRolePromoter(i){if(i===0)return 'Dirección de Cadetes; en su ausencia, cualquier Director';if(i===1)return 'Dirección de Agentes';if(i===2)return 'Dirección de Cuerpo Élite';if(i===7||i===8||i===9)return 'Founders (designaciones y ascensos superiores)';return i<=4?'Dirección autorizada hasta R5; Managers hasta R7 y Founders hasta R10':'Managers hasta R7; Founders hasta R10'}
function deaRankOffers(){const now=new Date();const active=now<new Date('2026-12-01T00:00:00+01:00');const offers=[['Supervisor',130,25,60,10],['Director',240,75,150,15],['Delegado',500,180,360,20]];return '<section class="dea-rank-offers"><span class="section-kicker">RANGOS DEA · HABBO</span><h2>Compra de rangos</h2><p>El ingreso ordinario a DEA es gratuito. Las compras de rango se gestionan exclusivamente con la dirección dentro de Habbo; la web no realiza cobros ni concede rangos automáticamente.</p><div class="dea-offer-grid">'+offers.map(([name,normal,promo,base,mission])=>'<article class="dea-offer-card"><h3>'+name+'</h3>'+(active?'<span class="dea-offer-label">OFERTA DE APERTURA · HASTA EL 30 NOV 2026</span><div class="dea-offer-price">'+promo+' c</div><del>'+normal+' c</del><p>Ahorra '+(normal-promo)+' créditos</p>':'<div class="dea-offer-price">'+normal+' c</div><p>Precio habitual</p>')+'<small>Desglose habitual: rango '+base+' c + misiones de '+mission+' c cada una (total '+normal+' c).</small></article>').join('')+'</div><p class="dim">Promoción activa desde el 24 de octubre hasta el 30 de noviembre de 2026, inclusive. A partir del 1 de diciembre se muestra el precio habitual. Confirma disponibilidad y condiciones con la dirección DEA.</p></section>'}
const DEA_WEEKLY_TOTALS=['','17 c','27 c','31 c','35 c','39 c','47 c','69 c','70 c (referencia)','80 c base semanal + comisiones'];
const DEA_PAY_DETAILS=['Sin nómina indicada','Base 7 c · total semanal 17 c','Base 12 c · total semanal 27 c','Base 14 c · total semanal 31 c','Base 16 c (configuración existente, pendiente de cotejo) · total semanal 35 c','Base 18 c · total semanal 39 c','Base 22 c · total ordinario 44 c · con bonificación 47 c','Base 33 c · total semanal 69 c','Base 35 c · referencia semanal 70 c · comisión por ventas 15 %','Base semanal 80 c · comisión por ventas 30 % · primera paga 40 c + comisión; segunda paga pendiente de detalle'];
function deaOfficialFunctions(){return '<section class="dea-functions"><div class="section-kicker">DOCUMENTACIÓN OFICIAL DEA</div><h2>Funciones, ascensos y nóminas · R1–R10</h2><p class="dim">Según «Tareas y Nóminas de acuerdo al rango». Las condiciones no indicadas se mantienen pendientes de aclaración. Dos horas extra como máximo con bonificación de 3c; periodicidad no especificada.</p>'+DEA_OFFICIAL_ROLES.map((r,i)=>{const g=GROUPS[i];const subs=g&&g.ranks.length?g.ranks.map(esc).join(' · '):'Subrangos pendientes de definir';return '<details class="rank-row dea-role"><summary><div class="dea-role-heading"><strong>R'+(i+1)+' · '+esc(r[0])+'</strong>'+(i===8||i===9?'<small class="dea-sales-commission">VENTAS · '+(i===8?'15 %':'30 %')+' de comisión</small>':'')+'<small class="dea-role-subranks">'+subs+'</small><div class="dea-role-meta">'+deaChatLabel('R'+(i+1))+'<span>Ascenso: '+esc(r[2])+'</span></div><div class="dea-role-promoter">Asciende: '+esc(deaRolePromoter(i))+'</div></div>'+I('chevron')+'</summary><div class="rank-inner"><div class="dea-role-stats"><span>Horas: <b>'+esc(r[3])+'</b></span><span>Nómina: <b>'+esc(r[4])+'</b></span><span>Total semanal: <b>'+esc(DEA_WEEKLY_TOTALS[i]||'No indicado')+'</b></span></div><p class="dea-pay-breakdown">'+esc(DEA_PAY_DETAILS[i])+'</p><h4>Funciones oficiales</h4><ul>'+r[5].map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul></div></details>'}).join('')+'</section>'}

const DEA_SALA_RULES=["No bailar dentro de la sala.","No gritar ni utilizar mayúsculas excesivas.","No decir groserías ni utilizar lenguaje ofensivo.","No hacer spam ni repetir mensajes innecesariamente.","No usar efectos, respetos o acciones que interrumpan el trabajo.","No sentarse en el suelo.","No interrumpir a los empleados mientras atienden a los usuarios.","No pedir ascensos, pagos o créditos de manera insistente.","No utilizar placas, uniformes o rangos que no correspondan.","Respetar el uniforme y la vestimenta oficial de DEA.","No utilizar insultos, provocaciones ni comportamientos que generen conflictos."];
function deaSalaNormas(){return '<section class="dea-sala-normas" id="normas-sala"><div class="section-kicker">NORMATIVA OFICIAL</div><h2>Normas de la sala DEA</h2><p class="dim">Reglas de convivencia y comportamiento en la sala de Habbo.</p><ol>'+DEA_SALA_RULES.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol></section>'}
function deaWorkFeature(){return '<a class="dea-work-feature" href="#/publico/como-trabajar" aria-label="Cómo trabajar en DEA: guía oficial de funciones, ascensos, horarios y nóminas"><span class="dea-work-feature-icon">'+I('book',true)+'</span><span class="dea-work-feature-copy"><small>GUÍA OFICIAL · DEA HABBO ES</small><strong>¿CÓMO TRABAJAR EN DEA?</strong><span>Aprende qué hacer en cada rango, cómo ascender y cómo funcionan las nóminas.</span><em>10 rangos · Funciones oficiales · Guía paso a paso</em></span><span class="dea-work-feature-arrow">'+I('arrow',true)+'</span></a>'}
function publicQuickLinks(){const links=[['publico','Inicio público','home'],['publico/noticias','DEA Confidencial','book','NEW'],['publico/sala','La sala DEA','home','NEW'],['publico/agencia','La agencia','shield'],['publico/founders','Founders','crown'],['publico/departamentos','Departamentos','users'],['publico/jerarquia','Rangos y ascensos','list'],['publico/como-trabajar','Cómo trabajar en DEA','book'],['publico/ingreso','Cómo ingresar','user'],['publico/placas','Placas de beneficio','spark'],['publico/compra-rangos','Compra de rangos','wallet','NEW'],['publico/banderines','Banderines','shield'],['publico/normativa','Normativa','book']];return `<nav class="dea-public-quick-links" aria-label="Accesos rápidos a las secciones públicas">${links.map(([path,label,icon,soon])=>`<a class="dea-public-quick-link" href="#/${path}" aria-label="${esc(label)}">${I(icon,true)}<span>${esc(label)}</span>${soon?'<small class="dea-menu-new">NEW</small>':''}</a>`).join('')}</nav>`+deaWorkFeature()}
function publicContent(p){if(p==='publico'){return publicQuickLinks()+head('DEA · HABBO HOTEL','Departamento Especial de Agentes','Una agencia organizada para aprender, progresar y colaborar dentro de Habbo Hotel.')+`<div class="columns"><div class="panel cyan"><div class="switch-head"><img class="logo-mini" src="./logo-dea-es.png" alt="DEA ES"><h3>Bienvenido a DEA HABBO ES</h3></div><p>Descubre nuestro sistema de formación, jerarquía y departamentos. El ingreso inicial comienza en la sala de Habbo y continúa en la web desde R2.</p><div class="btn-row"><a class="btn" href="#/publico/ingreso">Cómo ingresar ${I('arrow')}</a><a class="btn ghost" href="#/publico/jerarquia">Ver rangos</a></div></div><div class="panel gold"><h3>Identidad DEA</h3><p>Disciplina · Honor · Lealtad. Esta plataforma reúne información pública y, cuando se active, expedientes privados y gestión de dirección.</p><p class="dim">Proyecto de fans independiente, no vinculado oficialmente a Habbo Hotel.</p></div></div><div class="tiles three spaced">${tile('book','Formación en sala','45 min')}${tile('shield','Primer expediente oficial','R2')}${tile('crown','Founders','4',true)}</div>`}
if(p==='publico/agencia')return head('INSTITUCIONAL','Nuestra agencia','Información clara sobre la estructura de DEA HABBO ES.')+`<div class="columns equal"><div class="panel cyan"><h3>Qué es DEA</h3><p>DEA es una agencia de agentes organizada en Habbo Hotel. La web facilita el acceso a la información, la progresión y los procedimientos internos.</p><h3>Cómo funcionamos</h3><p>La formación inicial se realiza en la sala. Los expedientes web comienzan a partir de R2 · Agente de Enlace, una vez que dirección aprueba el alta.</p></div><div class="panel"><h3>Áreas principales</h3><div class="status-list">${['Control de Ascensos','Marketing','Eventos','Publicidad','Recursos Humanos','Desarrollo Web'].map(x=>`<div class="status-item">${I('check')}<strong>${x}</strong></div>`).join('')}</div></div></div>`;
if(p==='publico/noticias')return head('ACTUALIDAD · DEA HABBO ES','DEA Confidencial','El periódico oficial de la agencia: comunicados, novedades y promociones.')+`<section class="dea-paper dea-classified"><div class="dea-classified-desk"><div class="dea-classified-folder-tab">ARCHIVO CENTRAL · EXPEDIENTE 001</div><div class="dea-classified-sheet"><div class="dea-classified-stamp">CLASIFICADO</div><div class="dea-paper-masthead"><span>✦ DEA HABBO ES ✦</span><strong>DEA CONFIDENCIAL</strong><em>ARCHIVOS CLASIFICADOS · DOCUMENTACIÓN DESCLASIFICADA</em><small>🇪🇸 ESPAÑA · SÁBADO, 24 OCTUBRE 2026 · 16:50 H (CEST)</small></div><div class="dea-paper-edition">EDICIÓN Nº 001 · PREINAUGURACIÓN <span>OFERTAS DE APERTURA</span></div><div class="dea-classified-visual"><div class="dea-classified-photo"><img src="/assets/dea/sala-completa.webp" alt="Sede oficial DEA Habbo" loading="lazy"><small>FOTOGRAFÍA Nº 001 · SEDE DEA</small></div><div class="dea-classified-brief"><span>INFORME OFICIAL</span><b>OPERACIÓN PREINAUGURACIÓN</b><p>Promociones de rangos y acceso VIP permanente.</p><div class="dea-classified-seal">DOCUMENTO AUTORIZADO</div></div></div><article class="dea-paper-lead"><span>COMUNICADO OFICIAL · 24/10/2026</span><h2>¡La preinauguración de DEA viene con promociones especiales!</h2><p>Forma parte de la comunidad DEA HABBO ES. Durante nuestra preinauguración puedes consultar ofertas de acceso a determinados rangos y conocer la placa VIP permanente. La incorporación ordinaria como agente sigue siendo gratuita.</p></article><div class="dea-paper-rule"><span>ANEXO A · FICHAS DE RANGOS</span></div><div class="dea-paper-deals">${[['SUPERVISOR',130,25],['DIRECTOR',240,75],['DELEGADO',500,180]].map(([name,regular,promo])=>`<article class="dea-paper-deal"><span>PRECIO DE PREINAUGURACIÓN</span><h3>${name}</h3><div class="dea-paper-prices"><strong>${promo} <small>créditos</small></strong><del>${regular} c</del></div><p>Ahorras ${regular-promo} créditos</p></article>`).join('')}</div><p class="dea-paper-fine">Promoción de rangos vigente hasta el 30 de noviembre de 2026, inclusive. Sujeta a confirmación de disponibilidad y condiciones con la dirección de DEA. No se realizan pagos ni asignaciones automáticas desde esta web.</p><article class="dea-paper-vip"><div><span>ANEXO B · PLACA DE BENEFICIO · VIP DEA</span><h2>Tu acceso a DEA, para siempre</h2><p>Con la placa VIP puedes <strong>entrar y salir de la sala DEA cuando quieras</strong> como visitante. Sigue formando parte de nuestra comunidad y disfruta de un acceso permanente, sin caducidad.</p><p class="dea-paper-vip-price">DURACIÓN: DE POR VIDA · PRECIO: PREGUNTAR EN SALA</p><small>El VIP no otorga poderes sobre la sala, permisos de gestión ni autorización para trabajar como agente.</small></div><a href="#/publico/placas" class="btn gold">Conocer el VIP ↗</a></article><div class="dea-paper-footer"><span>¿TE INTERESA ALGUNA OFERTA?</span><p>Pregunta directamente a los Founders en la sala oficial de DEA en Habbo.</p><a href="https://www.habbo.es/room/126071884" target="_blank" rel="noopener noreferrer" class="btn gold">Visitar la sala DEA ↗</a><a href="#/publico/compra-rangos" class="btn">Ver condiciones de los rangos ↗</a></div></div></div></section>`;

if(p==='publico/sala')return head('SEDE OFICIAL · HABBO HOTEL','La sala DEA','Visita nuestra sede oficial en Habbo Hotel.')+`<section class="panel dea-room-panel dea-room-pixel"><div class="dea-room-kicker">✦ DEA HABBO ES · SEDE OFICIAL ✦</div><h3>✦ AGENCIA OFICIAL DEA ✦</h3><p class="dea-room-lead">Nuestra sede en Habbo Hotel. Un punto de encuentro para la formación, la organización de rangos y las actividades de la agencia.</p><div class="dea-room-identity"><span>NOMBRE DE LA SALA EN HABBO HOTEL</span><strong>AGENCIA OFICIAL DEA</strong><small>Para encontrarla, busca «AGENCIA OFICIAL DEA» en el navegador de salas o utiliza el acceso directo.</small><div class="dea-room-link">https://www.habbo.es/room/126071884</div><div class="dea-room-actions"><a class="btn gold" href="https://www.habbo.es/room/126071884" target="_blank" rel="noopener noreferrer">Entrar en la sala ↗</a><button class="btn dea-room-copy" type="button" data-action="copy-dea-room">Copiar enlace</button></div></div><div class="dea-room-teaser"><img class="dea-room-photo" src="/assets/dea/sala-completa.webp" alt="Vista de la sede DEA en Habbo Hotel" loading="lazy" onerror="this.remove();this.parentElement.classList.add('dea-room-teaser-no-image')"><div class="dea-room-teaser-overlay"><span>✦ NUESTRA SEDE ✦</span><strong>SEDE OFICIAL DEA</strong><small>Visita nuestra agencia en Habbo Hotel.</small></div></div></section>`;
if(p==='publico/banderines'){const banners=[["CEO",0],["Mánager",1],["Líder",9],["Delegado",8],["Director",7],["Supervisor",6],["Logística",5],["Cuerpo de Elite",4],["Agente",3],["Formacion",2]];return head('IDENTIDAD CORPORATIVA DEA','Banderines DEA','Los diez banderines identificativos de los grupos de DEA en Habbo Hotel.')+`<section class="dea-banner-intro"><span class="section-kicker">COLECCIÓN DEA · 10 GRUPOS</span><h3>Banderines de la agencia</h3><p>Los diez grupos DEA ordenados de mayor a menor rango, con sus insignias originales de Habbo.</p></section><div class="dea-banner-grid">${banners.map(([name,sprite],i)=>`<article class="dea-banner-unit"><div class="dea-banner-pole" aria-hidden="true"></div><div class="dea-banner-cloth dea-banner-color-${i%5}"><img class="dea-banner-real-insignia" src="/assets/dea/insignias/${({CEO:"fundador",Fundador:"fundador","Mánager":"manager",Líder:"lider",Delegado:"delegado",Director:"director",Supervisor:"supervisor","Logística":"logistica","Cuerpo de Elite":"cuerpo_de_elite",Agente:"agente",Formacion:"formacion"})[name]}.png?v=20261024-0850" alt="Insignia original [DEA] ${esc(name)}" loading="lazy" onerror="if(!this.dataset.backup){this.dataset.backup='1';this.src='https://raw.githubusercontent.com/PiterSC10/DEA-habbo-ES/main/assets/dea/insignias/'+this.src.split('/').pop().split('?')[0]}else{this.style.display='none'}"><span class="dea-banner-tag">DEA</span><strong>${esc(name)}</strong><small>BANDERÍN ${String(i+1).padStart(2,'0')}</small></div><div class="dea-banner-caption">[DEA] ${esc(name)}</div></article>`).join('')}</div>`}
if(p==='publico/jerarquia')return fullAscensionTable();
if(p==='publico/compra-rangos')return head('TIENDA DE RANGOS · HABBO','Compra de rangos','Consulta los precios habituales y la promoción de apertura vigente hasta el 30 de noviembre de 2026.')+deaRankOffers();
if(p==='publico/como-trabajar')return head('MANUAL OPERATIVO OFICIAL','Cómo trabajar en DEA','Consulta las funciones oficiales, colores de chat, ascensos, horas y nóminas de cada rango.')+deaOfficialFunctions();
if(p==='publico/placas')return publicPlaques();
if(p==='publico/departamentos')return head('ESTRUCTURA','Departamentos DEA','Seis áreas organizativas para coordinar el trabajo de la agencia.')+`<div class="tiles three">${['Control de Ascensos','Marketing','Eventos','Publicidad','Recursos Humanos','Desarrollo Web'].map((n,i)=>`<div class="panel"><div class="section-kicker">DEPARTAMENTO 0${i+1}</div><h3>${n}</h3><p class="dim">Responsabilidades y equipo definidos por dirección. Información detallada pendiente de publicación oficial.</p></div>`).join('')}</div>`;
if(p==='publico/founders')return head('DIRECCIÓN GENERAL','Equipo fundador','Cuatro Founders con sus avatares de Habbo y un árbol organizativo preparado para futuros nombramientos.')+founders();
if(p==='publico/ingreso')return head('PROCESO DE INGRESO','Cómo unirse a DEA','Primero completas la formación en la sala y después solicitas el alta digital.')+`<div class="steps">${[['01','Cadete','Comienzas la formación en la sala Habbo'],['02','Aspirante a Operador','Primer tramo: 15 minutos'],['03','Operador en Práctica','Siguiente tramo: 15 minutos'],['04','Agente de Enlace','A los 45 minutos, alta oficial R2 previa comprobación']].map(s=>`<div class="step"><div class="number">${s[0]}</div><strong>${s[1]}</strong><small>${s[2]}</small></div>`).join('')}</div><div class="footer-cta"><h3>¿Has completado la formación?</h3><p class="dim">Solicita tu expediente con tu cuenta Discord y tu nickname de Habbo. Un Founder debe aprobarlo.</p><a href="#/unete" class="btn">Únete a DEA ${I('arrow')}</a></div>`;
if(p==='publico/normativa')return head('DOCUMENTACIÓN','Normativa básica','Normas informativas, sujetas a las decisiones y actualizaciones de los Founders.')+deaSalaNormas()+`<div class="slim stack">${[['Respeto y convivencia','Se espera respeto hacia compañeros, superiores y visitantes en todo momento.'],['Ascensos','Desde R2, cada ascenso exige cumplir el plazo y la normativa del rango, presencia real en sala de Habbo y autorización de un Founder. Ningún ascenso es automático.'],['Identificación','Cada expediente oficial se asociará a una cuenta de Discord y un nombre de Habbo verificado.'],['Nóminas y asistencia','Nóminas ordinarias los miércoles y sábados. Se permite seleccionar varios agentes y aplicar la tarifa por rango, tras comprobar presencialmente en Habbo las horas exigidas y el pago. La paga extra del sábado es independiente, variable y requiere aprobación de Founders.'],['Placas de beneficio','Catálogo previsto de 6 a 8 placas, todavía pendiente de definición y aprobación. Venta exclusiva por Founders; solicitud, comprobación en la sala de Habbo, aprobación, entrega y activación presencial, caducidad y registro en el expediente. No se venden ni activan placas aún.'],['Compra de rangos','El ingreso ordinario es gratuito. Precios habituales totales: Supervisor 130 créditos (rango 60 c + misiones de 10 c), Director 240 créditos (rango 150 c + misiones de 15 c), Delegado 500 créditos (rango 360 c + misiones de 20 c). Oferta de apertura solo en noviembre de 2026: 25 c, 75 c y 180 c, respectivamente. Gestión exclusivamente presencial con la dirección DEA en Habbo, previa confirmación. No hay cobro ni ascenso automático en la web.'],['Protección de datos','Los expedientes son privados. Los agentes solo podrán consultar su ficha personal.']].map(([n,t])=>`<details class="rank-row"><summary><strong>${n}</strong>${I('chevron')}</summary><div class="rank-inner">${t}</div></details>`).join('')}</div>`;
return publicContent('publico')}
function accessArea(which){const vip=which==='vip';return head(vip?'CENTRO DE CONTROL':'EXPEDIENTE PERSONAL',vip?'ACCESO VIP':'ÁREA DE AGENTES',vip?'Identificación exclusiva de Founders autorizados mediante Discord.':'Entra con Discord para consultar únicamente tu expediente personal.')+`<div class="auth-cover"><img src="./logo-dea-es.png" alt="Escudo oficial DEA"><div class="panel gold"><h3>${vip?'Centro de Control DEA':'Ficha personal DEA'}</h3><p>Entrarás con Discord, pero dentro de DEA aparecerá tu nick Habbo registrado, junto a tu identidad Discord e ID. La confirmación de Founders será obligatoria para los agentes.</p><a class="btn gold" href="#/identificacion/${vip?'vip':'agente'}" rel="noopener noreferrer">${I('lock')} Entrar con Discord ${I('arrow')}</a></div></div>`}
function loginGate(p){
 const kind=p.split('/')[1]||'vip';
 const caption=kind==='vip'?'CENTRO VIP (SOLO FOUNDERS)':kind==='alta'?'INGRESO Y FICHA DE AGENTES':'EXPEDIENTE PERSONAL';
 const previous=kind==='vip'?'vip':'unete';
 return head(kind==='vip'?'ACCESO PRIVADO · FOUNDERS':'ÚNETE A DEA · AGENTES',kind==='vip'?'Identificación VIP':'Identificación de agentes',`Accede al ${caption} mediante una cuenta auténtica de Discord. Introducir un usuario o un correo nunca da permisos por sí solo.`)+
 `<div class="discord-auth-unified panel gold"><div class="section-kicker">VERIFICACIÓN OFICIAL</div><h3>${I('lock')} Acceso con Discord</h3><p>Si ya has iniciado sesión con la cuenta correcta, continúa directamente con Discord.</p><a class="btn gold discord-login-button" href="${DEA_PORTAL}?start=direct" rel="noopener noreferrer">${I('lock')} ENTRAR DIRECTAMENTE CON DISCORD ${I('arrow')}</a><div class="discord-login-separator"><span>O verifica tu usuario y correo con Discord</span></div><form class="discord-user-form" action="${DEA_PORTAL}" method="post" accept-charset="utf-8"><input type="hidden" name="login_mode" value="manual"><label for="discord-account-name"><strong>Usuario de Discord</strong><span class="dim">Tu usuario real, no el de Habbo.</span></label><input id="discord-account-name" name="discord_username" type="text" autocomplete="off" autocapitalize="none" spellcheck="false" maxlength="32" minlength="2" pattern="[a-zA-Z0-9_.]{2,32}" required placeholder="Ejemplo: usuario.discord"><label for="discord-account-email"><strong>Correo electrónico de Discord</strong><span class="dim">Debe ser el correo verificado de esa cuenta.</span></label><input id="discord-account-email" name="discord_email" type="email" autocomplete="off" spellcheck="false" maxlength="254" required placeholder="tu-correo@ejemplo.com"><button class="btn gold discord-login-button" type="submit">${I('shield')} ACEPTAR Y VERIFICAR CON DISCORD ${I('arrow')}</button></form><p class="dim spaced">Discord te pedirá que autorices la identidad. El servidor comparará el usuario y el correo verificado devueltos por Discord. ${kind==='vip'?'Para entrar al Centro VIP, el ID de Discord deberá pertenecer a un Founder activo autorizado.':'Dentro de DEA aparecerá tu nick de Habbo como nombre principal y también tu ID de Discord. Podrás solicitar el alta R2 o consultar solo tu propia ficha según el estado aprobado por Founders.'}</p></div><div class="panel discord-account-help"><h3>${I('shield')} ¿Tienes otra cuenta de Discord abierta?</h3><p>Cambia a la cuenta correcta en Discord y vuelve a iniciar sesión. Un usuario o correo escrito aquí no cambia la sesión activa del navegador.</p><a class="btn ghost" href="https://discord.com/channels/@me" target="_blank" rel="noopener noreferrer">Cambiar cuenta en Discord ${I('external')}</a><a class="btn ghost" href="#/${previous}">${I('back')} Volver</a><p class="dim">DEA no solicita ni almacena contraseñas. El formulario envía usuario y correo exclusivamente al backend privado para verificarlos mediante Discord; no los publica en GitHub.</p></div>`;
}
function joinPage(){return head('ADMISIÓN OFICIAL','Únete a DEA','Tu ingreso oficial comienza en R2 · Agente de Enlace, después de completar los 45 minutos de formación en Habbo.')+`<div class="columns equal"><div class="panel cyan"><h3>Antes de solicitar el ingreso</h3><div class="status-list">${[['Cadete','Primer tramo de formación'],['Aspirante a Operador','Segundo tramo'],['Operador en Práctica','Tercer tramo'],['Agente de Enlace','R2 · Alta oficial tras verificación']].map(([a,b])=>`<div class="status-item">${I('check')}<div><strong>${a}</strong><p>${b}</p></div></div>`).join('')}</div></div><div class="panel gold"><h3>Solicitud de ingreso</h3><p>Entra con Discord: se conservarán tu usuario y tu ID de Discord. Después escribe tu nombre de Habbo, aunque sea diferente. Ese será tu nombre visible en DEA, pendiente de confirmación por un Founder.</p><a class="btn gold" href="#/identificacion/alta" rel="noopener noreferrer">${I('user')} Acceder con Discord ${I('arrow')}</a><p class="dim spaced">Solicitar el ingreso no supone un ascenso automático.</p></div></div>`}
function agentPage(){return accessArea('agent')}
function vipPage(){return accessArea('vip')}

// Preinauguración: pantalla de cortesía que oculta las vistas a visitantes casuales.
// IMPORTANTE: una puerta JavaScript no protege el código ni los archivos públicos de GitHub Pages.
// Para seguridad real restringir el alojamiento y la visibilidad del repositorio.
// La portada requiere el acceso temporal; Apps Script sigue validando las cuentas privadas.
const PUBLIC_SITE_LIVE=true;
const PREVIEW_DIGEST='fa11ed11235b9348315045244896b2f5a08210cdb108c7d5c8239c3e2d02d1dd';
const PREVIEW_SESSION_KEY='dea_v6_preview_admitted';
let previewError='';
function previewUnlocked(){
 try{return typeof sessionStorage!=='undefined'&&sessionStorage.getItem(PREVIEW_SESSION_KEY)==='yes'}catch{return false}
}
function previewShell(){
 return `<div class="dea-preview-page"><div class="dea-preview-halo" aria-hidden="true"></div>
 <header class="dea-preview-top"><img src="./logo-dea-es.png" alt="Escudo oficial DEA HABBO ES"><span>DEA HABBO ES<small>DEPARTAMENTO ESPECIAL DE AGENTES</small></span></header>
 <main class="dea-preview-container"><div class="dea-preview-illustration" aria-hidden="true"><img src="./aguila-dea-original.jpg" alt=""></div>
 <div class="dea-preview-surface"><div class="dea-preview-eyebrow">PRÓXIMAMENTE · PREINAUGURACIÓN</div><h1>DEA HABBO ES</h1>
 <p>Estamos preparando la próxima etapa de nuestra agencia. El acceso a la vista previa está reservado a las personas invitadas.</p>
 <form data-preview-login class="dea-preview-login" autocomplete="off"><label for="dea-preview-user">Usuario de acceso</label>
 <input id="dea-preview-user" name="preview_user" type="text" autocomplete="off" autocapitalize="none" spellcheck="false" minlength="3" maxlength="80" required placeholder="Usuario" />
 <label for="dea-preview-pass">Contraseña de acceso</label>
 <input id="dea-preview-pass" name="preview_password" type="password" autocomplete="off" minlength="8" maxlength="128" required placeholder="Contraseña" />
 <button class="btn gold" type="submit">${I('lock')} Entrar a la vista previa ${I('arrow')}</button>
 ${previewError?`<p role="alert" class="dea-preview-error">${esc(previewError)}</p>`:''}
 </form><small class="dea-preview-caption">Acceso temporal de preinauguración. Las cuentas de Discord se comprueban después, dentro de DEA.</small><div class="dea-preview-counter">${deaPlate()}</div>
 </div></main><footer class="dea-preview-footer">DEA HABBO ES · Preinauguración</footer></div>`;
}
async function validatePreview(form){
 const user=String(form.elements.preview_user.value||'').trim().toLowerCase();
 const pass=String(form.elements.preview_password.value||'');
 const combined=new TextEncoder().encode(user+'\n'+pass);
 if(typeof crypto==='undefined'||!crypto.subtle){previewError='No se puede comprobar el acceso en este navegador. Utiliza una conexión HTTPS.';render();return}
 const digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',combined))).map(b=>b.toString(16).padStart(2,'0')).join('');
 if(digest===PREVIEW_DIGEST){
  try{sessionStorage.setItem(PREVIEW_SESSION_KEY,'yes')}catch{}
  previewError='';location.hash='#/inicio';render()
 }else{previewError='Usuario o contraseña incorrectos.';render()}
}

// Titulares y descripciones editoriales de secciones preparadas para SEO.
// La portada y las guías públicas están preparadas para la indexación; las operaciones privadas siguen en Apps Script.
const PAGE_SEO={
 inicio:['DEA HABBO ES | Agencia Habbo, rangos y formación','Conoce DEA HABBO ES, comunidad independiente de Habbo Hotel. Formación, rangos e ingreso gratuito.'],
 publico:['DEA HABBO ES | Agencia Habbo y comunidad','Descubre DEA HABBO ES, su organización, normas, rangos y actividades en Habbo Hotel.'],
 'publico/agencia':['La agencia DEA HABBO ES | Habbo Hotel','Conoce el Departamento Especial de Agentes, comunidad independiente de Habbo Hotel.'],
 'publico/jerarquia':['Rangos y ascensos | DEA HABBO ES','Tabla completa de ascensos, plazos, nóminas y tarifas oficiales R1–R10.'],
 'publico/placas':['Placas de beneficio | DEA HABBO ES','Catálogo de placas DEA, pendiente de aprobación de Founders.'],
 'publico/noticias':['Noticias DEA HABBO ES','Noticias y comunicados de la agencia DEA HABBO ES.'],
 'publico/sala':['Sala DEA HABBO ES | Próximamente','Próximamente: presentación de la sede DEA dentro de Habbo Hotel.'],
 'publico/banderines':['Banderines DEA HABBO ES | Próximamente','Próximamente: catálogo público de banderines DEA.'],
 'publico/departamentos':['Departamentos de DEA HABBO ES','Descubre los departamentos y la organización de nuestra comunidad dentro de Habbo Hotel.'],
 'publico/ingreso':['Cómo unirse gratis a DEA HABBO ES','Consulta cómo ingresar en DEA HABBO ES y comenzar la formación dentro de Habbo Hotel.'],
 'publico/normativa':['Normativa de DEA HABBO ES | Habbo','Conoce las normas y el funcionamiento de DEA HABBO ES.'],
 'publico/founders':['Founders de DEA HABBO ES','Información sobre la dirección de DEA HABBO ES.'],
 vip:['Acceso VIP privado | DEA HABBO ES','Zona privada de Founders autorizados.'],
 'identificacion/vip':['Identificación VIP | DEA HABBO ES','Identificación privada de Founders mediante Discord.'],
 'identificacion/alta':['Registro de agentes | DEA HABBO ES','Identificación de agentes mediante Discord para iniciar una solicitud.'],
 'identificacion/agente':['Mi expediente | DEA HABBO ES','Acceso privado al expediente individual de un agente.']
};
function updatePageSeo(path){
 const [title,description]=PAGE_SEO[path]||['DEA HABBO ES | Comunidad Habbo','DEA HABBO ES, comunidad independiente de Habbo Hotel.'];
 document.title=title;
 // Mejora la navegación y el texto compartido por visitantes; la indexación sigue bloqueada.
 if(typeof document.querySelector==='function'){
  const meta=document.querySelector('meta[name="description"]');
  if(meta)meta.setAttribute('content',description);
 }
}
function render(){
 const previousSideScroll=ROOT.querySelector('#dea-side-scroll')?.scrollTop||0;
 if(!PUBLIC_SITE_LIVE && !previewUnlocked()){
  ROOT.innerHTML=previewShell();
  document.title='Preinauguración | DEA HABBO ES';
  if(typeof document.querySelector==='function'){
   const meta=document.querySelector('meta[name="description"]');
   if(meta)meta.setAttribute('content','DEA HABBO ES está preparando su inauguración. Acceso temporal reservado a personas invitadas.');
  }
  return;
 }
 const p=pathname(),a=area(p);
 if(a==='inicio'){ROOT.innerHTML=layoutHome();updatePageSeo('inicio');return}
 const body=p.startsWith('identificacion/')?loginGate(p):a==='publico'?publicContent(p):a==='unete'?loginGate('identificacion/alta'):a==='vip'?vipPage():agentPage();
 ROOT.innerHTML=internalShell(p,body);
 const newSideScroll=ROOT.querySelector('#dea-side-scroll');if(newSideScroll)newSideScroll.scrollTop=previousSideScroll;
 updatePageSeo(PAGE_SEO[p]?p:a);
}
ROOT.addEventListener('click',e=>{const el=e.target.closest('[data-route],[data-action]');if(!el)return;if(el.dataset.route){e.preventDefault();route(el.dataset.route);mobileOpen=false;render();return}switch(el.dataset.action){case 'copy-dea-room':return;case 'toggle-sidebar':if(innerWidth<711){mobileOpen=!mobileOpen}else sidebarOpen=!sidebarOpen;break;case 'mobile-menu':mobileOpen=!mobileOpen;break;case 'close-mobile':mobileOpen=false;break;case 'exit-preview':try{sessionStorage.removeItem(PREVIEW_SESSION_KEY)}catch{}previewError='';location.hash='#/inicio';break;}render()});
ROOT.addEventListener('click',async e=>{const btn=e.target.closest('[data-action="copy-dea-room"]');if(!btn)return;e.stopPropagation();try{await navigator.clipboard.writeText('https://www.habbo.es/room/126071884');btn.textContent='✓ Enlace copiado';setTimeout(()=>{if(btn.isConnected)btn.textContent='Copiar enlace'},2200)}catch{btn.textContent='Selecciona y copia el enlace mostrado'}});
ROOT.addEventListener('click',e=>{const modal=ROOT.querySelector('[data-dea-modal]');if(!modal)return;if(e.target.closest('[data-dea-open]')){modal.hidden=false;modal.querySelector('[data-dea-close]').focus()}else if(e.target.closest('[data-dea-close]')||e.target===modal)modal.hidden=true});
ROOT.addEventListener('keydown',e=>{if(e.key==='Escape'&&mobileOpen){mobileOpen=false;render();return}const modal=ROOT.querySelector('[data-dea-modal]');if(e.key==='Escape'&&modal)modal.hidden=true;if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-dea-open]')){e.preventDefault();e.target.click()}});
ROOT.addEventListener('submit',e=>{if(!e.target.matches('[data-preview-login]'))return;e.preventDefault();void validatePreview(e.target)});
window.addEventListener('hashchange',()=>{mobileOpen=false;window.scrollTo(0,0);render()});
render();
